import decimal

def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    rates = {
        "inland": decimal.Decimal("4.20"),
        "coastal": decimal.Decimal("5.75"),
        "highland": decimal.Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")
    if weight_kg <= 0:
        raise ValueError("weight must be greater than zero")

    weight = decimal.Decimal(str(weight_kg))
    base = rates[zone]

    if weight <= decimal.Decimal("10"):
        subtotal = weight * base
    elif weight <= decimal.Decimal("50"):
        subtotal = decimal.Decimal("10") * base
        subtotal += (weight - decimal.Decimal("10")) * base * decimal.Decimal("0.60")
    else:
        subtotal = decimal.Decimal("10") * base
        subtotal += decimal.Decimal("40") * base * decimal.Decimal("0.60")
        subtotal += (weight - decimal.Decimal("50")) * base * decimal.Decimal("0.35")

    subtotal = subtotal.quantize(decimal.Decimal("0.01"), rounding=decimal.ROUND_HALF_UP)

    if subtotal == subtotal.to_integral_value():
        subtotal -= decimal.Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += decimal.Decimal("18.50")

    return float(subtotal.quantize(decimal.Decimal("0.01"), rounding=decimal.ROUND_HALF_UP))
